const preferences = new Map<string, boolean>()

export function getPreference(userId: string): boolean {
  return preferences.get(userId) ?? false
}

export function setPreference(userId: string, enabled: boolean): void {
  preferences.set(userId, enabled)
}

'use server'

import { revalidatePath } from 'next/cache'
import { getPreference, setPreference } from '@/lib/preferences'

const CURRENT_USER_ID = 'user-1'

export async function toggleNotifications(): Promise<void> {
  const current = getPreference(CURRENT_USER_ID)
  setPreference(CURRENT_USER_ID, !current)
  revalidatePath('/')
}

import { getPreference } from '@/lib/preferences'
import { toggleNotifications } from './actions'

const CURRENT_USER_ID = 'user-1'

export default function Home() {
  const enabled = getPreference(CURRENT_USER_ID)

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

export const metadata = {
  title: 'Notification Settings',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
